package com.bank.surge.db;

import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

// Simulated database with a bounded connection pool and slow reads.
public class AccountDatabase {
    private static final Logger log = Logger.getLogger(AccountDatabase.class.getName());
    private final Map<String, BigDecimal> balances = new HashMap<>();
    private final int poolSize;
    private final AtomicInteger inFlight = new AtomicInteger(0);
    private int totalDbReads = 0;

    public AccountDatabase(int poolSize) {
        this.poolSize = poolSize;
        balances.put("SAV2001", new BigDecimal("1000000"));
        balances.put("CUR3001", new BigDecimal("250000"));
    }

    public BigDecimal readBalance(String accountId) {
        int active = inFlight.incrementAndGet();
        try {
            if (active > poolSize) {
                log.severe(() -> "DB pool exhausted (active=" + active + " > " + poolSize + ")");
                throw new RuntimeException("connection pool exhausted");
            }
            totalDbReads++;
            return balances.getOrDefault(accountId, BigDecimal.ZERO);
        } finally {
            inFlight.decrementAndGet();
        }
    }

    public int getTotalDbReads() { return totalDbReads; }
}
