package com.bank.surge.cache;

import com.bank.surge.db.AccountDatabase;
import java.math.BigDecimal;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

// Cache-aside: check cache first, on miss read DB and populate with a TTL.
public class BalanceCache {
    private static final Logger log = Logger.getLogger(BalanceCache.class.getName());
    private final AccountDatabase db;
    private final long ttlMillis;
    private final Map<String, long[]> timestamps = new ConcurrentHashMap<>();
    private final Map<String, BigDecimal> store = new ConcurrentHashMap<>();
    private int hits = 0;
    private int misses = 0;

    public BalanceCache(AccountDatabase db, long ttlMillis) {
        this.db = db;
        this.ttlMillis = ttlMillis;
    }

    public synchronized BigDecimal getBalance(String accountId) {
        long now = System.currentTimeMillis();
        long[] ts = timestamps.get(accountId);
        if (ts != null && now - ts[0] <= ttlMillis) {
            hits++;
            return store.get(accountId);                 // cache hit (microseconds)
        }
        misses++;
        BigDecimal value = db.readBalance(accountId);     // cache miss → DB
        store.put(accountId, value);
        timestamps.put(accountId, new long[]{now});
        return value;
    }

    public int getHits() { return hits; }
    public int getMisses() { return misses; }
    public double hitRate() {
        int total = hits + misses;
        return total == 0 ? 0.0 : (double) hits / total;
    }
}
