package com.bank.surge.scaling;

import java.util.logging.Logger;

// HPA-like: adjust replica count toward target utilization per instance.
public class AutoScaler {
    private static final Logger log = Logger.getLogger(AutoScaler.class.getName());
    private final int minReplicas;
    private final int maxReplicas;
    private final int targetRpsPerInstance;
    private int replicas;

    public AutoScaler(int minReplicas, int maxReplicas, int targetRpsPerInstance) {
        this.minReplicas = minReplicas;
        this.maxReplicas = maxReplicas;
        this.targetRpsPerInstance = targetRpsPerInstance;
        this.replicas = minReplicas;
    }

    // Reconcile replica count against current requests-per-second.
    public int reconcile(int currentRps) {
        int desired = (int) Math.ceil((double) currentRps / targetRpsPerInstance);
        desired = Math.max(minReplicas, Math.min(maxReplicas, desired));
        if (desired != replicas) {
            int from = replicas;
            int to = desired;
            log.warning(() -> "AUTO-SCALE rps=" + currentRps + " replicas " + from + " -> " + to);
            replicas = desired;
        }
        return replicas;
    }

    public int getReplicas() { return replicas; }
}
