package com.bank.surge.async;

import java.util.concurrent.*;
import java.util.logging.Logger;

// Offloads slow work (statements, SMS) so the request path returns fast.
public class AsyncWorkQueue {
    private static final Logger log = Logger.getLogger(AsyncWorkQueue.class.getName());
    private final BlockingQueue<Runnable> queue = new LinkedBlockingQueue<>();
    private int processed = 0;

    // Request path just enqueues — returns immediately (the shock absorber).
    public void submit(String description, Runnable work) {
        queue.offer(() -> { work.run(); processed++; });
        log.fine(() -> "QUEUED async work: " + description + " (depth=" + queue.size() + ")");
    }

    // Consumers drain at a steady rate regardless of the producer burst.
    public void drain(int maxItems) {
        for (int i = 0; i < maxItems; i++) {
            Runnable r = queue.poll();
            if (r == null) break;
            r.run();
        }
        log.info(() -> "DRAINED async queue, processed-so-far=" + processed
                + " remaining=" + queue.size());
    }

    public int queueDepth() { return queue.size(); }
    public int getProcessed() { return processed; }
}
