package com.bank.surge;

import com.bank.surge.async.AsyncWorkQueue;
import com.bank.surge.cache.BalanceCache;
import com.bank.surge.db.AccountDatabase;
import com.bank.surge.scaling.AutoScaler;
import java.util.logging.*;

public class SurgeDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(SurgeDemo.class.getName());

        AccountDatabase db = new AccountDatabase(30);         // pool size 30
        BalanceCache cache = new BalanceCache(db, 30000);     // 30s TTL
        AutoScaler scaler = new AutoScaler(3, 30, 500);       // 500 rps/instance
        AsyncWorkQueue async = new AsyncWorkQueue();

        // Normal load: 1500 rps.
        scaler.reconcile(1500);
        for (int i = 0; i < 1500; i++) cache.getBalance("SAV2001");
        log.info("Normal load cache hit rate: " + pct(cache.hitRate()));

        // SURGE: 10x spike to 15000 rps.
        log.severe("TRAFFIC SURGE: 1500 rps -> 15000 rps");
        scaler.reconcile(15000);

        // Caching absorbs the read surge; only misses touch the DB.
        for (int i = 0; i < 15000; i++) cache.getBalance("SAV2001");
        log.info("Surge cache hit rate: " + pct(cache.hitRate())
                + ", total DB reads (not 16500!): " + db.getTotalDbReads());

        // Writes offload slow work asynchronously so requests stay fast.
        for (int i = 0; i < 500; i++) {
            async.submit("statement+SMS for transfer " + i, () -> { /* generate PDF, send SMS */ });
        }
        log.info("Async queue depth after surge of writes: " + async.queueDepth());
        async.drain(500);

        log.info("Final: replicas=" + scaler.getReplicas()
                + ", cache hits=" + cache.getHits() + ", async processed=" + async.getProcessed());
    }

    private static String pct(double v) { return String.format("%.1f%%", v * 100); }
}

